// === Tab: mySketch ===
let epiColors, S;

function setup() {
	createCanvas(windowWidth, windowHeight);
	S = max(width, height) / random(2, 6);
	strokeWeight(4);
	noFill();
	loop();

	const { EpiColors } = EpiColorsPckg;
	epiColors = new EpiColors();
}

function draw() {
	background(8, 8, 24);
	// noLoop() removed for animation

	const SZE = S * 0.5;
	for (let y = 0; y < height-S; y += SZE) {		
		for (let x = 0; x < width-S; x += SZE) {
			drawCell(x, y, S, S);
		}
	}
}

function drawCell(x, y, w, h) {
	epiColors.getRandomPalette();

	const p1 = createVector(x + random(0.2, 0.3)*w, y + random(0.7, 0.9)*h);
	const p2 = createVector(x + random(0.7, 0.9)*w, y + random(0.7, 0.9)*h);

	const a1a = createVector(x + random(0.0, 0.5)*w, y + random(0.1, 0.6)*h);
	const a1b = createVector(x + random(0.0, 0.5)*w, y + random(0.1, 0.6)*h);

	const a2a = createVector(x + random(0.5, 1.0)*w, y + random(0.1, 0.6)*h);
	const a2b = createVector(x + random(0.5, 1.0)*w, y + random(0.1, 0.6)*h);

	const num = epiColors.palette.length;
	for (let i = 0; i < num; i++) {
		const f = i/(num-1);
		const a1 = p5.Vector.lerp(a1a, a1b, f);
		const a2 = p5.Vector.lerp(a2a, a2b, f);
		const pa = p5.Vector.lerp(p1, p2, f/10);
		const pb = p5.Vector.lerp(p1, p2, 1-f/10);

		stroke(epiColors.palette[i]);
		bezier(pa.x, p1.y, a1.x, a1.y, a2.x, a2.y, pb.x, p2.y);
		// bezier(pa.x, pa.y, a1.x, a1.y, a2.x, a2.y, pb.x, pb.y);
	}
}

function mousePressed() {
	if (mouseButton != RIGHT && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > 0.1*width) {
		setup();
	}
}
